const long long MOD = 1'000'000'007;
long long pw(long long a, long long b, long long m = MOD) {
    long long r = 1;
    a %= m;
    for (; b; b >>= 1, a = a * a % m)
        if (b & 1) r = r * a % m;
    return r;
}
