long long memo[100];
long long fib(int n) {
    if (n < 2) return n;
    if (memo[n]) return memo[n];
    return memo[n] = fib(n - 1) + fib(n - 2);
}
vector<long long> pierwsze;
for (int i = 0; i < 10; i++) pierwsze.push_back(fib(i));
